import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.BbQrW5_t.js";const p=JSON.parse('{"title":"《AI Agent 实战》第四章核心知识点","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/04-chapter4.md","filePath":"study/ai-agent-book/04-chapter4.md","lastUpdated":1785465991000}'),d={name:"study/ai-agent-book/04-chapter4.md"};function i(o,t,n,h,s,g){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="《ai-agent-实战》第四章核心知识点" tabindex="-1">《AI Agent 实战》第四章核心知识点 <a class="header-anchor" href="#《ai-agent-实战》第四章核心知识点" aria-label="Permalink to &quot;《AI Agent 实战》第四章核心知识点&quot;">​</a></h1><h2 id="一、工具分类框架" tabindex="-1">一、工具分类框架 <a class="header-anchor" href="#一、工具分类框架" aria-label="Permalink to &quot;一、工具分类框架&quot;">​</a></h2><h3 id="五类工具总览" tabindex="-1">五类工具总览 <a class="header-anchor" href="#五类工具总览" aria-label="Permalink to &quot;五类工具总览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具类型</th><th>调用方向</th><th>作用对象</th></tr></thead><tbody><tr><td>感知工具</td><td>Agent 主动调用</td><td>获取信息</td></tr><tr><td>执行工具</td><td>Agent 主动调用</td><td>改变世界</td></tr><tr><td>协作工具</td><td>Agent 主动调用</td><td>驱动其他 Agent 或人类</td></tr><tr><td>用户沟通工具</td><td>Agent 主动调用</td><td>向用户传递信息</td></tr><tr><td>事件触发工具</td><td>Agent 注册、外部触发</td><td>驱动 Agent 开始执行</td></tr></tbody></table><h3 id="各类工具详解" tabindex="-1">各类工具详解 <a class="header-anchor" href="#各类工具详解" aria-label="Permalink to &quot;各类工具详解&quot;">​</a></h3><p><strong>感知工具</strong>：Agent获取外部信息的主要渠道</p><ul><li>示例：web_search、knowledge_base_search、fetch_url、find_file、grep_file、read_file</li><li>核心：粒度权衡 + 输出信息量控制</li></ul><p><strong>执行工具</strong>：Agent改变外部世界的方式</p><ul><li>示例：shell_exec、code_interpreter、write_file、edit_file、send_email</li><li>核心：错误代价高，安全约束是设计核心</li></ul><p><strong>协作工具</strong>：Agent与其他Agent及人类协作的方式</p><ul><li>示例：spawn_subagent、send_message_to_subagent、cancel_subagent、list_agents</li><li>用途：并行执行、使用不同模型/工具/提示词执行不同任务</li></ul><p><strong>用户沟通工具</strong>：Agent主动向用户传递信息的方式</p><ul><li>示例：reply_to_user、send_card_to_user、send_user_notification</li><li>背景：多渠道异步消息场景下，&quot;说话&quot;成为显式工具调用</li></ul><p><strong>事件触发工具</strong>：外部世界驱动Agent行动的方式</p><ul><li>示例：set_timer、monitor_shell、connect_channel</li><li>关键：注册时Agent主动调用，触发时由外部事件异步回调</li></ul><hr><h2 id="二、工具设计的通用原则" tabindex="-1">二、工具设计的通用原则 <a class="header-anchor" href="#二、工具设计的通用原则" aria-label="Permalink to &quot;二、工具设计的通用原则&quot;">​</a></h2><h3 id="_1-能力表达形式选择" tabindex="-1">1. 能力表达形式选择 <a class="header-anchor" href="#_1-能力表达形式选择" aria-label="Permalink to &quot;1. 能力表达形式选择&quot;">​</a></h3><p><strong>专用代码工具</strong> vs <strong>Skill + 通用执行器</strong></p><table tabindex="0"><thead><tr><th>形态</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>专用代码工具</td><td>结构化、可测试、确定性高</td><td>占token多，数量膨胀破坏KV Cache</td></tr><tr><td>Skill + 通用执行器</td><td>灵活、省token、覆盖场景广</td><td>依赖模型能力</td></tr></tbody></table><p><strong>决策三维度</strong>：</p><ul><li>参数复杂度：复杂嵌套对象用专用工具，简单参数可用CLI</li><li>变更频率：频繁变化用Skill，稳定操作用专用工具</li><li>模型能力：SOTA模型可用Skill方式，弱模型需结构化schema引导</li></ul><h3 id="_2-工具粒度权衡" tabindex="-1">2. 工具粒度权衡 <a class="header-anchor" href="#_2-工具粒度权衡" aria-label="Permalink to &quot;2. 工具粒度权衡&quot;">​</a></h3><p><strong>整合标准</strong>：功能相似性 + 使用场景重叠度</p><p>整合优势：</p><ul><li>降低LLM认知负担</li><li>描述更清晰</li><li>便于扩展</li></ul><p>整合边界：参数形态差异大、延迟特性不同、使用频率极高时保持独立</p><h3 id="_3-工具通用性设计" tabindex="-1">3. 工具通用性设计 <a class="header-anchor" href="#_3-工具通用性设计" aria-label="Permalink to &quot;3. 工具通用性设计&quot;">​</a></h3><p><strong>核心原则</strong>：通用工具优于专用工具，除非存在明确的安全/权限/性能理由</p><p>示例：<code>code_interpreter</code> 比十几个专用计算器更省token、更灵活</p><p><strong>边界</strong>：需要特殊权限、复杂配置、安全风险的操作需要专用工具</p><h3 id="_4-工具描述的艺术" tabindex="-1">4. 工具描述的艺术 <a class="header-anchor" href="#_4-工具描述的艺术" aria-label="Permalink to &quot;4. 工具描述的艺术&quot;">​</a></h3><p><strong>核心</strong>：让LLM知道&quot;什么时候用&quot;，而不只是&quot;能做什么&quot;</p><p>关键要素：</p><ul><li>使用时机说明（如&quot;当需要获取实时信息或查找未知事实时使用&quot;）</li><li>边界条件（做不到什么、不接受什么输入）</li><li>参数描述用具体例子代替抽象规范</li><li>返回值结构说明</li><li>执行代价标注</li><li>1-5个真实调用示例（准确率可从72%提升到90%）</li></ul><p><strong>调试原则</strong>：Agent频繁选错工具时，优先检查工具描述而非怀疑模型能力</p><h3 id="_5-参数传递的保真性" tabindex="-1">5. 参数传递的保真性 <a class="header-anchor" href="#_5-参数传递的保真性" aria-label="Permalink to &quot;5. 参数传递的保真性&quot;">​</a></h3><p><strong>红线</strong>：模型感知的世界与工具操作的世界之间，不能存在系统性偏差</p><p><strong>反模式</strong>：</p><ul><li>静默输入转换（如Cursor弯引号转直引号导致匹配失败）</li><li>静默参数注入（如自动附加git commit参数导致报错）</li></ul><p><strong>要求</strong>：参数传递必须透明，必须修改时要在工具描述中说明</p><h3 id="_6-工具设计演进三阶段" tabindex="-1">6. 工具设计演进三阶段 <a class="header-anchor" href="#_6-工具设计演进三阶段" aria-label="Permalink to &quot;6. 工具设计演进三阶段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>代际</th><th>特点</th></tr></thead><tbody><tr><td>第一代</td><td>直接API封装，粒度过细</td></tr><tr><td>第二代</td><td>ACI原则：工具对应Agent目标而非底层API</td></tr><tr><td>第三代</td><td>优化调用/串联/发现方式：示例驱动、动态发现、代码编排执行</td></tr></tbody></table><hr><h2 id="三、工具生态-mcp协议" tabindex="-1">三、工具生态：MCP协议 <a class="header-anchor" href="#三、工具生态-mcp协议" aria-label="Permalink to &quot;三、工具生态：MCP协议&quot;">​</a></h2><h3 id="mcp核心设计" tabindex="-1">MCP核心设计 <a class="header-anchor" href="#mcp核心设计" aria-label="Permalink to &quot;MCP核心设计&quot;">​</a></h3><p><strong>架构</strong>：客户端-服务器架构</p><ul><li>MCP服务器：暴露一组工具</li><li>MCP客户端（Agent框架/IDE）：通过标准化协议通信</li></ul><p><strong>关键决策</strong>：</p><ol><li>标准化工具描述格式（JSON Schema）</li><li>传输层灵活：本地stdio / 远程Streamable HTTP</li><li>原语分离：工具（执行）| 资源（只读）| 提示模板</li></ol><h3 id="mcp的价值与局限" tabindex="-1">MCP的价值与局限 <a class="header-anchor" href="#mcp的价值与局限" aria-label="Permalink to &quot;MCP的价值与局限&quot;">​</a></h3><p><strong>价值</strong>：一次开发，处处可用</p><p><strong>局限</strong>：</p><ul><li>请求-响应式，缺乏跨会话事件驱动标准</li><li>工具描述注入上下文开销大（5个服务器约55K token）</li></ul><p><strong>缓解方案</strong>：</p><ul><li>文件系统作为上下文接口（默认只看工具名索引，按需查询定义）</li><li>总token消耗可减少46.9%</li></ul><h3 id="mcp安全风险" tabindex="-1">MCP安全风险 <a class="header-anchor" href="#mcp安全风险" aria-label="Permalink to &quot;MCP安全风险&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风险类型</th><th>说明</th><th>缓解措施</th></tr></thead><tbody><tr><td>工具描述投毒</td><td>恶意服务器在description中夹带指令</td><td>接入前审查工具描述</td></tr><tr><td>恶意/被劫持服务器</td><td>供应链攻击或服务器被入侵</td><td>锁定服务器版本</td></tr><tr><td>同名工具遮蔽</td><td>恶意服务器遮蔽正规工具</td><td>最小权限凭证配置</td></tr><tr><td>凭证管理风险</td><td>Agent持有OAuth token/API key</td><td>设置有效期，不复用高权限凭证</td></tr></tbody></table><h3 id="工具发现方法" tabindex="-1">工具发现方法 <a class="header-anchor" href="#工具发现方法" aria-label="Permalink to &quot;工具发现方法&quot;">​</a></h3><ol><li><strong>检索式预筛选</strong>：按语义相似度一次性匹配（局限：无法预见后续步骤需求）</li><li><strong>主动声明发现</strong>：Agent声明能力缺口，系统动态匹配注入（MCP-Zero）</li><li><strong>层次化匹配</strong>：服务器级→工具级两层语义路由</li><li><strong>Skills渐进式披露</strong>：Agent启动只看目录，按需查阅详细定义</li></ol><hr><h2 id="四、感知工具设计要点" tabindex="-1">四、感知工具设计要点 <a class="header-anchor" href="#四、感知工具设计要点" aria-label="Permalink to &quot;四、感知工具设计要点&quot;">​</a></h2><h3 id="核心挑战" tabindex="-1">核心挑战 <a class="header-anchor" href="#核心挑战" aria-label="Permalink to &quot;核心挑战&quot;">​</a></h3><p>返回信息量远超Agent处理能力（数万字符搜索结果、上百页PDF）</p><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h3><p><strong>上下文感知压缩</strong>：输出超阈值（如10000字符）时，基于查询意图自动压缩</p><p><strong>搜索类工具</strong>：</p><ul><li>返回结构化候选列表（标题、位置、摘要）</li><li>支持分页/游标，默认返回前若干条</li></ul><p><strong>读取类工具</strong>：</p><ul><li>支持offset/limit参数</li><li>截断时显式可见（注明省略内容和读取方式）</li></ul><p><strong>只读性红利</strong>：</p><ul><li>结果可安全缓存</li><li>多个感知调用可并行执行</li></ul><p><strong>多模态感知</strong>：</p><ul><li>纯文字用文本提取</li><li>布局敏感内容（UI、表格、设计稿）保留图像</li></ul><hr><h2 id="五、执行工具安全机制" tabindex="-1">五、执行工具安全机制 <a class="header-anchor" href="#五、执行工具安全机制" aria-label="Permalink to &quot;五、执行工具安全机制&quot;">​</a></h2><h3 id="层次化安全防护体系" tabindex="-1">层次化安全防护体系 <a class="header-anchor" href="#层次化安全防护体系" aria-label="Permalink to &quot;层次化安全防护体系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>机制</th><th>说明</th></tr></thead><tbody><tr><td>第一层</td><td>输入验证</td><td>检查路径遍历、命令注入、参数格式，快速失败</td></tr><tr><td>第二层</td><td>权限控制</td><td>工作目录限制、禁止命令黑名单、配额检查</td></tr><tr><td>第三层</td><td>智能审查</td><td>提议者-审核者机制、Sidecar机制</td></tr></tbody></table><h3 id="提议者-审核者机制" tabindex="-1">提议者-审核者机制 <a class="header-anchor" href="#提议者-审核者机制" aria-label="Permalink to &quot;提议者-审核者机制&quot;">​</a></h3><p><strong>事前审批</strong>：</p><ul><li>提议模型：行动导向，任务完成</li><li>审批模型：风险控制，规则遵守</li><li>模型选择：不同家族、相似能力水平（认知多样性）</li></ul><p><strong>事后验证</strong>：</p><ul><li>模态切换检验结果（代码→渲染截图，配置→沙盒运行）</li></ul><h3 id="sidecar机制" tabindex="-1">Sidecar机制 <a class="header-anchor" href="#sidecar机制" aria-label="Permalink to &quot;Sidecar机制&quot;">​</a></h3><p><strong>定义</strong>：伴随主Agent思考循环运行的轻量级LLM调用，对工具调用做独立安全判断</p><p><strong>关键设计</strong>：</p><ul><li>只看结构化字段（工具名、参数），不看主模型自由文本</li><li>与主模型流式输出并行运行</li><li>亚秒级完成</li></ul><p><strong>对比提议者-审核者</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>提议者-审核者</th><th>Sidecar</th></tr></thead><tbody><tr><td>执行时机</td><td>操作前/操作后</td><td>与流式输出并行</td></tr><tr><td>审查对象</td><td>操作合理性/结果</td><td>操作本身</td></tr><tr><td>输入隔离</td><td>提议者和审查者看相似信息</td><td>刻意隔离主模型自由文本</td></tr></tbody></table><h3 id="自动验证闭环" tabindex="-1">自动验证闭环 <a class="header-anchor" href="#自动验证闭环" aria-label="Permalink to &quot;自动验证闭环&quot;">​</a></h3><p><strong>原则</strong>：如果操作结果可以被验证，就应该自动验证</p><p>示例：write_file后立即执行语法检查（linter），返回结构化错误列表</p><h3 id="幂等性与取消语义" tabindex="-1">幂等性与取消语义 <a class="header-anchor" href="#幂等性与取消语义" aria-label="Permalink to &quot;幂等性与取消语义&quot;">​</a></h3><p><strong>幂等性</strong>：同一操作执行一次和多次，影响完全相同</p><p>实现手段：</p><ul><li>携带唯一标识（idempotency key）</li><li>先查询后变更</li></ul><p><strong>不可幂等操作</strong>（发送邮件、转账）：采用&quot;预检-确认&quot;两段式</p><h3 id="执行环境隔离" tabindex="-1">执行环境隔离 <a class="header-anchor" href="#执行环境隔离" aria-label="Permalink to &quot;执行环境隔离&quot;">​</a></h3><table tabindex="0"><thead><tr><th>隔离层级</th><th>机制</th><th>特点</th></tr></thead><tbody><tr><td>OS级</td><td>sandbox-exec、seccomp</td><td>轻量本地方案</td></tr><tr><td>容器</td><td>Docker</td><td>独立文件系统/网络栈，共享内核</td></tr><tr><td>microVM/虚拟机</td><td>Firecracker</td><td>独立内核，硬件级隔离</td></tr></tbody></table><p><strong>注意</strong>：Python venv不是沙盒，只隔离包依赖</p><hr><h2 id="六、协作工具设计" tabindex="-1">六、协作工具设计 <a class="header-anchor" href="#六、协作工具设计" aria-label="Permalink to &quot;六、协作工具设计&quot;">​</a></h2><h3 id="子agent设计哲学" tabindex="-1">子Agent设计哲学 <a class="header-anchor" href="#子agent设计哲学" aria-label="Permalink to &quot;子Agent设计哲学&quot;">​</a></h3><p><strong>核心价值</strong>：专业化分工——各子Agent独立优化提示词、工具集、知识库</p><h3 id="子agent提示词关键要素" tabindex="-1">子Agent提示词关键要素 <a class="header-anchor" href="#子agent提示词关键要素" aria-label="Permalink to &quot;子Agent提示词关键要素&quot;">​</a></h3><ol><li><strong>角色定义清晰</strong>：&quot;你是专门负责XXX的助手Agent&quot;</li><li><strong>上下文来源标注</strong>：<code>[FROM_MAIN_AGENT]</code>、<code>[FROM_USER]</code>、<code>[TOOL_RESULT]</code></li><li><strong>任务边界界定</strong>：职责范围内/外</li><li><strong>输出格式标准化</strong>：统一JSON结构</li></ol><h3 id="协作工具三组原语" tabindex="-1">协作工具三组原语 <a class="header-anchor" href="#协作工具三组原语" aria-label="Permalink to &quot;协作工具三组原语&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原语组</th><th>工具</th><th>说明</th></tr></thead><tbody><tr><td>启动与取消</td><td>spawn_subagent, cancel_subagent</td><td>创建/终止子Agent</td></tr><tr><td>消息传递</td><td>send_message_to_subagent</td><td>双向通信</td></tr><tr><td>发现</td><td>list_agents</td><td>列出可用Agent及状态</td></tr></tbody></table><h3 id="人工介入-hitl" tabindex="-1">人工介入（HITL） <a class="header-anchor" href="#人工介入-hitl" aria-label="Permalink to &quot;人工介入（HITL）&quot;">​</a></h3><p><strong>超时降级策略</strong>：</p><ul><li>设置超时阈值和默认行为</li><li>优先级队列（紧急多渠道，普通仅邮件）</li></ul><p><strong>反馈循环</strong>：人类批准/拒绝及理由构成反馈数据，进入经验知识或后训练数据</p><hr><h2 id="七、事件驱动的异步agent架构" tabindex="-1">七、事件驱动的异步Agent架构 <a class="header-anchor" href="#七、事件驱动的异步agent架构" aria-label="Permalink to &quot;七、事件驱动的异步Agent架构&quot;">​</a></h2><h3 id="为什么需要异步" tabindex="-1">为什么需要异步 <a class="header-anchor" href="#为什么需要异步" aria-label="Permalink to &quot;为什么需要异步&quot;">​</a></h3><p><strong>同步Agent局限</strong>：</p><ul><li>要么等待后台任务完成才能对话</li><li>要么等对话结束才能处理新事件</li></ul><p><strong>异步需求</strong>：</p><ul><li>异步执行是常态（长时间任务不阻塞交互）</li><li>事件优先级动态判断</li><li>中断和恢复流畅性</li></ul><p><strong>根本矛盾</strong>：LLM训练范式假设同步（发出工具调用后，下一条消息必须是工具结果），但真实部署要求异步</p><h3 id="事件触发工具三类" tabindex="-1">事件触发工具三类 <a class="header-anchor" href="#事件触发工具三类" aria-label="Permalink to &quot;事件触发工具三类&quot;">​</a></h3><ol><li><p><strong>定时器</strong>（set_timer）：处理依赖物理时间的事件</p><ul><li>一次性定时器：明确时间点任务</li><li>循环定时器：周期性任务</li></ul></li><li><p><strong>后台任务监控</strong>（monitor_shell）：监控长时间命令行任务</p></li><li><p><strong>外部事件通道</strong>（connect_channel）：实时推送新邮件、API回调、IM消息</p></li></ol><h3 id="用户沟通工具" tabindex="-1">用户沟通工具 <a class="header-anchor" href="#用户沟通工具" aria-label="Permalink to &quot;用户沟通工具&quot;">​</a></h3><p><strong>范式转变</strong>：从原生ReAct（assistant消息直接发给用户）到专用工具发送消息</p><p><strong>设计要点</strong>：</p><ul><li>支持异步消息模式</li><li>多渠道选择（IM、短信、邮件、电话）</li><li>消息一致性保持</li></ul><h3 id="虚拟身份与隔离执行环境" tabindex="-1">虚拟身份与隔离执行环境 <a class="header-anchor" href="#虚拟身份与隔离执行环境" aria-label="Permalink to &quot;虚拟身份与隔离执行环境&quot;">​</a></h3><p><strong>架构选择</strong>：Agent应拥有独立虚拟身份（专属通讯账号、存储、计算环境）</p><p><strong>优势</strong>：</p><ul><li>操作可追溯、可审计</li><li>错误不影响宿主系统</li></ul><p><strong>挑战</strong>：</p><ul><li>反自动化机制（CAPTCHA、IP信誉检测）</li><li>需要用户真实账号场景：Human-in-the-Loop认证</li></ul><h3 id="事件处理机制" tabindex="-1">事件处理机制 <a class="header-anchor" href="#事件处理机制" aria-label="Permalink to &quot;事件处理机制&quot;">​</a></h3><p><strong>事件循环核心</strong>：事件只在每轮循环的边界被消费</p><p><strong>事件结构化建模</strong>：</p><ul><li>来源（谁）：用户/联系人/陌生人/系统</li><li>渠道（方式）：电话/短信/IM/邮件/定时器</li><li>内容（什么）：文本/情感/紧急度</li><li>上下文（背景）：对话关联/任务关联</li></ul><h3 id="三种事件处理策略" tabindex="-1">三种事件处理策略 <a class="header-anchor" href="#三种事件处理策略" aria-label="Permalink to &quot;三种事件处理策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>适用场景</th><th>机制</th></tr></thead><tbody><tr><td>取消式处理</td><td>紧急事件（用户中断、监督指令）</td><td>主动制造安全点，清空队列，重新调用LLM</td></tr><tr><td>队列式处理</td><td>常规事件（工具结果、补充信息）</td><td>等待当前操作完成，批量追加到轨迹</td></tr><tr><td>并行处理</td><td>独立轻量级查询（如天气查询）</td><td>另起推理会话独立执行</td></tr></tbody></table><h3 id="工程权宜-模拟同步的异步实现" tabindex="-1">工程权宜：模拟同步的异步实现 <a class="header-anchor" href="#工程权宜-模拟同步的异步实现" aria-label="Permalink to &quot;工程权宜：模拟同步的异步实现&quot;">​</a></h3><p><strong>五条规则</strong>：</p><table tabindex="0"><thead><tr><th>规则</th><th>内容</th></tr></thead><tbody><tr><td>规则1</td><td>LLM输出时立即记录assistant message</td></tr><tr><td>规则2</td><td>工具调用完成时才记录tool result</td></tr><tr><td>规则3</td><td>工具执行中的打断需要占位符</td></tr><tr><td>规则4</td><td>LLM思考中的打断直接丢弃当前思考</td></tr><tr><td>规则5</td><td>非打断事件进入队列等待批处理</td></tr></tbody></table><p><strong>核心优势</strong>：常态下LLM看到完美的同步轨迹</p><p><strong>风险</strong>：占位符可能加剧幻觉</p><h3 id="异步工具接口设计" tabindex="-1">异步工具接口设计 <a class="header-anchor" href="#异步工具接口设计" aria-label="Permalink to &quot;异步工具接口设计&quot;">​</a></h3><p><strong>原则</strong>：从&quot;调用即完成&quot;到&quot;启动与完成解耦&quot;</p><p>示例：</p><ul><li><code>initiate_phone_call</code>：启动呼叫，立即返回任务ID</li><li>通话进展通过事件通知</li></ul><h3 id="未来方向-模型进化" tabindex="-1">未来方向：模型进化 <a class="header-anchor" href="#未来方向-模型进化" aria-label="Permalink to &quot;未来方向：模型进化&quot;">​</a></h3><p><strong>异步RL训练需要三种核心能力</strong>：</p><ol><li>理解轨迹中事件的异步穿插</li><li>恢复被打断的任务和思考</li><li>批量事件的综合处理</li></ol><p><strong>持续思考模式</strong>：用约两百行编排逻辑，让现成文本思考模型变成持续思考Agent</p><hr><h2 id="八、主动工具发现" tabindex="-1">八、主动工具发现 <a class="header-anchor" href="#八、主动工具发现" aria-label="Permalink to &quot;八、主动工具发现&quot;">​</a></h2><h3 id="现有方法对比" tabindex="-1">现有方法对比 <a class="header-anchor" href="#现有方法对比" aria-label="Permalink to &quot;现有方法对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>说明</th><th>局限</th></tr></thead><tbody><tr><td>全量注入</td><td>所有工具schema一次性注入</td><td>工具上千时失效</td></tr><tr><td>检索预筛选</td><td>按语义相似度一次性匹配</td><td>无法预见后续步骤需求</td></tr><tr><td>主动声明发现</td><td>Agent声明能力缺口，系统动态注入</td><td>需嵌入索引基础设施</td></tr><tr><td>Skills渐进式披露</td><td>启动只看目录，按需查阅</td><td>-</td></tr></tbody></table><h3 id="层次化匹配" tabindex="-1">层次化匹配 <a class="header-anchor" href="#层次化匹配" aria-label="Permalink to &quot;层次化匹配&quot;">​</a></h3><p>服务器级→工具级两层语义搜索：</p><ul><li>先按能力描述定位相关服务器</li><li>再在服务器内匹配具体工具</li><li>候选相似度低于阈值时返回&quot;未找到&quot;</li></ul><h3 id="动态加载与kv-cache" tabindex="-1">动态加载与KV Cache <a class="header-anchor" href="#动态加载与kv-cache" aria-label="Permalink to &quot;动态加载与KV Cache&quot;">​</a></h3><p><strong>关键</strong>：动态加载工具会破坏KV Cache</p><p><strong>解决</strong>：</p><ul><li>新工具schema追加到上下文末尾</li><li>静态前缀保持稳定，KV Cache复用</li><li>主流API原生支持：OpenAI Responses API、Claude Code</li></ul><h3 id="skills-按需查阅范式" tabindex="-1">Skills：按需查阅范式 <a class="header-anchor" href="#skills-按需查阅范式" aria-label="Permalink to &quot;Skills：按需查阅范式&quot;">​</a></h3><p><strong>特点</strong>：</p><ul><li>Agent启动只看目录（name + description，数百token）</li><li>按需读取sub-skill，顺着引用继续查阅</li><li>不需要嵌入索引，用通用文件阅读能力</li></ul><p><strong>KV Cache优化</strong>：skill的KV表示预编译并缓存，用RoPE重定位&quot;粘贴&quot;到任意位置</p><hr><h2 id="九、关键实验概览" tabindex="-1">九、关键实验概览 <a class="header-anchor" href="#九、关键实验概览" aria-label="Permalink to &quot;九、关键实验概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>实验</th><th>核心内容</th></tr></thead><tbody><tr><td>实验4-1</td><td>感知工具MCP服务器（搜索、多模态理解、文件系统、数据源）</td></tr><tr><td>实验4-2</td><td>执行工具MCP服务器（安全验证体系）</td></tr><tr><td>实验4-3</td><td>协作工具MCP服务器（子Agent管理、HITL）</td></tr><tr><td>实验4-4</td><td>事件驱动的邮件处理Agent（事件队列基础）</td></tr><tr><td>实验4-5</td><td>带并行执行和打断能力的异步Agent（深层工程）</td></tr><tr><td>实验4-6</td><td>主动工具发现（对比验证对小参数量模型的价值）</td></tr></tbody></table><hr><h2 id="十、核心结论" tabindex="-1">十、核心结论 <a class="header-anchor" href="#十、核心结论" aria-label="Permalink to &quot;十、核心结论&quot;">​</a></h2><ol><li><p><strong>工具设计质量决定Agent能力上限</strong>，异步架构决定Agent能否可靠运行</p></li><li><p><strong>ACI原则</strong>：工具应对应Agent目标而非底层API</p></li><li><p><strong>参数传递保真性</strong>是贯穿所有工具设计的底线</p></li><li><p><strong>执行工具安全</strong>需多层层防护：输入验证→权限控制→智能审查</p></li><li><p><strong>异步与同步矛盾</strong>：当前只能用工程手段缓解，根本解法需模型训练范式转变</p></li><li><p><strong>工具发现</strong>：Skills渐进式披露是更轻量、更现代的思路</p></li></ol><hr><h2 id="附录-关键术语" tabindex="-1">附录：关键术语 <a class="header-anchor" href="#附录-关键术语" aria-label="Permalink to &quot;附录：关键术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>定义</th></tr></thead><tbody><tr><td>ACI</td><td>Agent-Computer Interface，研究Agent如何与计算机交互</td></tr><tr><td>MCP</td><td>Model Context Protocol，AI模型与外部工具/数据源的通信标准</td></tr><tr><td>Sidecar</td><td>伴随主Agent思考的轻量级LLM安全校验机制</td></tr><tr><td>HITL</td><td>Human-In-The-Loop，人在回路</td></tr><tr><td>KV Cache</td><td>大模型推理时的缓存机制，存储已计算的注意力状态</td></tr><tr><td>幂等性</td><td>同一操作执行一次和多次，影响完全相同</td></tr><tr><td>提示注入</td><td>把恶意指令伪装成正常内容、诱导模型执行非预期操作</td></tr><tr><td>渐进式披露</td><td>不把所有信息一次性展示，按需逐步提供</td></tr></tbody></table>',175)])])}const c=a(d,[["render",i]]);export{p as __pageData,c as default};
